import{_ as d,C as r,o as n,c as o,E as a,a4 as i}from"./chunks/framework.BMj-uaUw.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"最后一次课，要做的是“交出去”","slug":"最后一次课-要做的是-交出去","link":"#最后一次课-要做的是-交出去","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit12/index.md","filePath":"unit12/index.md","lastUpdated":1789356894000}'),l={name:"unit12/index.md"};function h(s,t,g,c,u,p){const e=r("UnitMeta");return n(),o("div",null,[a(e,{unit:"单元 12",title:"联调优化部署与答辩",module:"模块五 · 综合项目实战",hours:"4 学时",week:"第 12 周",goals:["能用 Postman 或 Apifox 独立排查接口问题，说清是前端传错了还是后端返回错了","能读懂构建产物报告，并动手把首屏体积降下来","能把前端项目打包并部署到一台服务器上，用真实域名访问","能写出结构完整、数据可验证的交付文档，并完成一次 10 分钟答辩"],outcomes:["联调问题记录表","构建优化前后对比数据","线上可访问的地址","项目交付文档与答辩 PPT"]}),t[0]||(t[0]=i('<h2 id="最后一次课-要做的是-交出去" tabindex="-1">最后一次课，要做的是“交出去” <a class="header-anchor" href="#最后一次课-要做的是-交出去" aria-label="Permalink to &quot;最后一次课，要做的是“交出去”&quot;">​</a></h2><p>前面十一周，你写的是代码。这一周要做的是把代码变成<strong>别人能用的东西</strong>。</p><p>这两件事的距离比想象中大。学生的常见情况是：本地跑得好好的，一打包就白屏；或者部署上去了，刷新页面 404；或者交上去的文档只有一句“实现了活动管理功能”。</p><p>这个单元的四个小节，正好对应交付前的四道关：</p><table tabindex="0"><thead><tr><th>关卡</th><th>会出现的问题</th><th>在哪一节讲</th></tr></thead><tbody><tr><td>前后端对接</td><td>接口通了但字段对不上、跨域、token 失效</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>打包</td><td>产物 3 MB、首屏白屏 5 秒</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>部署</td><td>刷新 404、接口 404、资源加载失败</td><td><a href="/frontend-engineering-course/unit12/03-deploy.html">12.3</a></td></tr><tr><td>交付</td><td>文档说不清楚、答辩讲不到重点</td><td><a href="/frontend-engineering-course/unit12/04-delivery.html">12.4</a></td></tr></tbody></table><p><strong>四道关的顺序不能换。</strong> 先把功能调通，再考虑快不快；先能跑起来，再考虑放在哪跑；先自己确认好，再去讲给别人听。</p><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1 前后端联调</a></td><td>联调流程、字段核对、跨域、token 与 401、常见 4xx 排查</td><td>接口报错时能定位是谁的问题</td></tr><tr><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2 构建优化</a></td><td>产物分析、路由懒加载、按需引入、分包、图片处理</td><td>首屏体积从几 MB 降到几百 KB</td></tr><tr><td><a href="/frontend-engineering-course/unit12/03-deploy.html">12.3 部署上线</a></td><td>打包、Nginx 配置、history 模式回退、环境变量、域名与 HTTPS</td><td>得到一个能给别人访问的地址</td></tr><tr><td><a href="/frontend-engineering-course/unit12/04-delivery.html">12.4 交付材料与答辩</a></td><td>交付文档结构、README 写法、答辩 PPT 与讲稿、常见提问</td><td>把做过的事讲清楚</td></tr><tr><td><a href="/frontend-engineering-course/unit12/ai-collaboration.html">AI 协作 · 优化建议要先验证</a></td><td>部署配置的常见漏项、优化建议的测量方法、交付材料核对</td><td>没有测量就没有优化</td></tr></tbody></table><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>联调实操</td><td>1.2 学时</td><td>把前端接到真实（或同学写的）后端上，跑通登录 → 活动列表 → 新增活动这条链路</td></tr><tr><td>优化实操</td><td>1.0 学时</td><td>跑一次 <code>build</code>，看产物报告，做两三项优化，记录前后数据</td></tr><tr><td>部署实操</td><td>1.0 学时</td><td>打包、部署到服务器或静态托管平台，确认线上可访问</td></tr><tr><td>答辩与讲评</td><td>0.8 学时</td><td>每人 3 分钟讲核心思路与一个技术难点，同学互评</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易崩的地方</p><p><strong>一、等到最后一次课才开始联调。</strong> 单元 11 结束时，你应该已经用 mock 数据把功能做完了。如果你的后端同学也拖到今天才写完第一版接口，那这次课一定完不成 —— <strong>两边都有 bug 的时候，排查时间会翻好几倍。</strong></p><p>建议：<strong>单元 11 下课后就和后端同学约一次，先对字段，再接最简单的那个接口。</strong></p><p><strong>二、优化和部署没时间做。</strong> 有些同学把时间全花在补功能上，最后只是本地截了张图交差。<strong>“部署上线”是这门课的硬性要求</strong>，线上地址和本地截图的分量完全不同 —— 前者任何人都能打开，后者只能证明你的电脑上跑过。</p></div><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p><strong>一、联调问题记录表</strong></p><p>联调过程中一定会遇到问题。把每一个记下来：</p><table tabindex="0"><thead><tr><th>编号</th><th>现象</th><th>排查过程</th><th>定位</th><th>处理</th></tr></thead><tbody><tr><td>1</td><td>登录后跳转正常，但刷新就退回登录页</td><td>看 Application → Local Storage，token 在；看 Network，刷新后请求没带 token</td><td>请求拦截器在应用初始化前就创建了，拿不到 store 里的 token</td><td>拦截器里改成调用时才取 token</td></tr></tbody></table><p><strong>这张表比“功能都实现了”这句话有价值得多。</strong> 它证明你真的调通过，而不是抄了别人的代码。</p><p><strong>二、构建优化前后对比数据</strong></p><p>至少包含三项：</p><table tabindex="0"><thead><tr><th>指标</th><th>优化前</th><th>优化后</th></tr></thead><tbody><tr><td>产物体积（<code>dist</code> 总大小）</td><td></td><td></td></tr><tr><td>最大的单个 JS 文件</td><td></td><td></td></tr><tr><td>首屏 JS 体积（初始加载的 chunk 之和）</td><td></td><td></td></tr></tbody></table><p><strong>数据要真实。</strong> 跑两次 <code>build</code>，把终端输出和 <code>dist</code> 目录的大小截图留着。</p><p><strong>三、线上可访问的地址</strong></p><p>要求：</p><ul><li>用真实浏览器打开能正常登录、能看列表、能新增</li><li>直接刷新任何一个子路由（比如 <code>/activity</code>）不 404</li><li>地址不是 <code>localhost</code>，也不是只能在你自己电脑上访问的地址</li></ul><p><strong>四、项目交付文档与答辩 PPT</strong></p><p>交付文档至少包含：项目简介、技术栈、功能清单、如何本地运行、如何部署、已知问题。</p><p>答辩 PPT 5 到 8 页，10 分钟讲完，重点讲<strong>一个技术难点是怎么解决的</strong>。</p><p>具体的写法见 <a href="/frontend-engineering-course/unit12/04-delivery.html">12.4 交付材料与答辩</a>。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><ul><li><strong>功能已经做完了。</strong> 这个单元不写新功能，只做联调、优化、部署、交付。如果活动管理模块还没跑通，先回去补完单元 11 的必做题。</li><li><strong>有一台能部署的机器。</strong> 系里给的服务器、云厂商的学生服务器、或者静态托管平台（Vercel / Netlify / Cloudflare Pages 都可以）。</li><li><strong>Git 仓库是干净的。</strong> 部署时从仓库拉代码，本地有未提交的改动会漏文件。</li></ul><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>单元 12 是这门课的最后一站。做完之后你会有一个<strong>能被别人访问的线上项目</strong>和一份<strong>说得清来龙去脉的文档</strong> —— 这两样东西放在简历里，比“熟悉 Vue 3”这几个字有说服力得多。</p><p>下一步：<a href="/frontend-engineering-course/unit12/01-integration.html">12.1 前后端联调</a>。</p>',32))])}const m=d(l,[["render",h]]);export{f as __pageData,m as default};
